head.script:
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.checkHourInputScope = function() {
	return scwin.__getObj("inputCalendar2_calendar_selectbox_hour_itemTable_0").innerText == "9" && scwin.__getObj("inputCalendar2_calendar_selectbox_hour_itemTable_11").innerText == "20";
};
scwin.checkMinuteInputScope = function() {
	return scwin.__getObj("inputCalendar2_calendar_selectbox_minute_itemTable_0").innerText == "0" && scwin.__getObj("inputCalendar2_calendar_selectbox_minute_itemTable_11").innerText == "55";
};
scwin.checkSecondInputScope = function() {
	return scwin.__getObj("inputCalendar2_calendar_selectbox_second_itemTable_0").innerText == "0" && scwin.__getObj("inputCalendar2_calendar_selectbox_second_itemTable_11").innerText == "55";
};
scwin.checkHourScope = function() {
	return scwin.__getObj("calendar2_selectbox_hour_itemTable_0").innerText == "9" && scwin.__getObj("calendar2_selectbox_hour_itemTable_11").innerText == "20";
};
scwin.checkMinuteScope = function() {
	return scwin.__getObj("calendar2_selectbox_minute_itemTable_0").innerText == "0" && scwin.__getObj("calendar2_selectbox_minute_itemTable_11").innerText == "55";
};
scwin.checkSecondScope = function() {
	return scwin.__getObj("calendar2_selectbox_second_itemTable_0").innerText == "0" && scwin.__getObj("calendar2_selectbox_second_itemTable_11").innerText == "55";
};
scwin.setVal1 = function() {
	checkHour = scwin.checkHourInputScope();
};
scwin.setVal2 = function() {
	checkMinute = scwin.checkMinuteInputScope();
};
scwin.setVal3 = function() {
	checkSecond = scwin.checkSecondInputScope();
};
scwin.setVal4 = function() {
	checkHour = scwin.checkHourScope();
};
scwin.setVal5 = function() {
	checkMinute = scwin.checkMinuteScope();
};
scwin.setVal6 = function() {
	checkSecond = scwin.checkSecondScope();
};
